{
  "name": "opencode-sound-hooks",
  "version": "1.1.3",
  "description": "OpenCode plugin for audio feedback on session events - success, error, and permission sounds",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "opencode-sound-hooks": "dist/cli.js"
  },
  "type": "module",
  "files": [
    "dist",
    "assets",
    "README.md"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "sound",
    "audio",
    "notifications",
    "hooks"
  ],
  "author": "Israel Toledo",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/israeLToledo/opencode-sound-hooks"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.63",
    "@types/bun": "^1.3.9",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}

#!/usr/bin/env node
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { playFile } from "./audio.js";
import { DEFAULT_CONFIG_PATH, DEFAULT_VOLUME, SOUND_NAMES, WINDOWS_PROXIMITY_NOTIFICATION, defaultSoundPath, resolveConfig, writeConfig, } from "./config.js";
const runtimeFile = fileURLToPath(import.meta.url);
const runtimeDir = dirname(runtimeFile);
const packageDir = join(runtimeDir, "..");
const assetsDir = join(packageDir, "assets");
const soundLabel = {
    success: "session.idle (conclusao)",
    error: "session.error (falha)",
    question: "permission.ask (pergunta/interrupcao)",
};
const aliases = {
    success: "success",
    completion: "success",
    concluido: "success",
    concluida: "success",
    done: "success",
    error: "error",
    fail: "error",
    failed: "error",
    question: "question",
    ask: "question",
    prompt: "question",
};
const resolveSoundName = (value) => aliases[value.toLowerCase()];
const printHelp = () => {
    console.log(`opencode-sound-hooks

Comandos:
  list
    Mostra os sons atuais, evento de cada som e caminho.

  preview <success|error|question>
    Toca um som para teste imediato.

  set <success|error|question> <caminho>
    Define um arquivo .wav personalizado para o hook.

  volume <0-100>
    Define volume padrao do plugin (default: ${Math.round(DEFAULT_VOLUME * 100)}%).

  use-windows-default
    Define success para: ${WINDOWS_PROXIMITY_NOTIFICATION}

  reset <success|error|question>
    Restaura o som padrao desse hook.

Config:
  ${DEFAULT_CONFIG_PATH}
`);
};
const list = () => {
    const config = resolveConfig(assetsDir);
    console.log(`Config: ${config.path}`);
    console.log(`Volume: ${Math.round(config.volume * 100)}%`);
    SOUND_NAMES.forEach((name) => {
        const path = config.sounds[name];
        const status = existsSync(path) ? "ok" : "missing";
        console.log(`- ${name} -> ${soundLabel[name]} | ${status} | ${path}`);
    });
};
const preview = (name) => {
    const config = resolveConfig(assetsDir);
    const path = config.sounds[name];
    if (!existsSync(path)) {
        console.error(`Arquivo nao encontrado: ${path}`);
        process.exitCode = 1;
        return;
    }
    console.log(`Tocando ${name}: ${path}`);
    playFile(path, config.volume);
};
const setSound = (name, path) => {
    if (!existsSync(path)) {
        console.error(`Arquivo nao encontrado: ${path}`);
        process.exitCode = 1;
        return;
    }
    writeConfig({
        sounds: {
            [name]: path,
        },
    });
    console.log(`Som atualizado: ${name} -> ${path}`);
};
const setVolume = (value) => {
    const percent = Number(value);
    if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
        console.error("Volume invalido. Use um valor entre 0 e 100.");
        process.exitCode = 1;
        return;
    }
    writeConfig({
        volume: percent / 100,
    });
    console.log(`Volume atualizado: ${percent}%`);
};
const resetSound = (name) => {
    const path = defaultSoundPath(name, assetsDir);
    writeConfig({
        sounds: {
            [name]: path,
        },
    });
    console.log(`Som resetado: ${name} -> ${path}`);
};
const main = () => {
    const [command, ...args] = process.argv.slice(2);
    if (!command ||
        command === "help" ||
        command === "--help" ||
        command === "-h") {
        printHelp();
        return;
    }
    if (command === "list") {
        list();
        return;
    }
    if (command === "use-windows-default") {
        setSound("success", WINDOWS_PROXIMITY_NOTIFICATION);
        return;
    }
    if (command === "preview") {
        const sound = resolveSoundName(args[0] ?? "");
        if (!sound) {
            console.error("Som invalido para preview.");
            process.exitCode = 1;
            return;
        }
        preview(sound);
        return;
    }
    if (command === "set") {
        const sound = resolveSoundName(args[0] ?? "");
        const path = args[1];
        if (!sound || !path) {
            console.error("Uso: set <success|error|question> <caminho>");
            process.exitCode = 1;
            return;
        }
        setSound(sound, path);
        return;
    }
    if (command === "reset") {
        const sound = resolveSoundName(args[0] ?? "");
        if (!sound) {
            console.error("Uso: reset <success|error|question>");
            process.exitCode = 1;
            return;
        }
        resetSound(sound);
        return;
    }
    if (command === "volume") {
        const value = args[0];
        if (!value) {
            console.error("Uso: volume <0-100>");
            process.exitCode = 1;
            return;
        }
        setVolume(value);
        return;
    }
    console.error(`Comando desconhecido: ${command}`);
    printHelp();
    process.exitCode = 1;
};
main();
//# sourceMappingURL=cli.js.map

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { EVENT_TO_SOUND, SOUND_NAMES, WINDOWS_PROXIMITY_NOTIFICATION, defaultSoundPath, resolveConfig, } from "./config.js";
import { playFile } from "./audio.js";
const runtimeFile = fileURLToPath(import.meta.url);
const runtimeDir = dirname(runtimeFile);
const packageDir = join(runtimeDir, "..");
const assetsDir = join(packageDir, "assets");
const windowsCacheDir = join(process.env.TEMP ?? process.env.TMP ?? join(packageDir, ".tmp"), "opencode-sound-hooks");
const config = resolveConfig(assetsDir);
const soundBufferCache = new Map();
const windowsPathCache = new Map();
const ensureDirectory = (path) => {
    if (!existsSync(path)) {
        mkdirSync(path, { recursive: true });
    }
};
const loadSoundBuffers = () => {
    SOUND_NAMES.forEach((name) => {
        const configuredPath = config.sounds[name];
        const fallbackPath = defaultSoundPath(name, assetsDir);
        const path = existsSync(configuredPath) ? configuredPath : fallbackPath;
        if (!existsSync(path)) {
            return;
        }
        soundBufferCache.set(name, readFileSync(path));
        config.sounds[name] = path;
    });
};
const getWindowsPlayablePath = (name) => {
    const cached = windowsPathCache.get(name);
    if (cached) {
        return cached;
    }
    if (name === "success" && existsSync(WINDOWS_PROXIMITY_NOTIFICATION)) {
        windowsPathCache.set(name, WINDOWS_PROXIMITY_NOTIFICATION);
        return WINDOWS_PROXIMITY_NOTIFICATION;
    }
    const sourcePath = config.sounds[name];
    if (!existsSync(sourcePath)) {
        return null;
    }
    const data = soundBufferCache.get(name);
    if (!data) {
        return sourcePath;
    }
    ensureDirectory(windowsCacheDir);
    const cachedPath = join(windowsCacheDir, `${name}.wav`);
    if (!existsSync(cachedPath)) {
        writeFileSync(cachedPath, data);
    }
    windowsPathCache.set(name, cachedPath);
    return cachedPath;
};
const warmWindowsCache = () => {
    if (process.platform !== "win32") {
        return;
    }
    SOUND_NAMES.forEach((name) => {
        getWindowsPlayablePath(name);
    });
};
const playSound = (name) => {
    const path = process.platform === "win32"
        ? getWindowsPlayablePath(name)
        : config.sounds[name];
    if (!path || !existsSync(path)) {
        return;
    }
    playFile(path, config.volume);
};
loadSoundBuffers();
warmWindowsCache();
export const SoundHooksPlugin = async () => {
    return {
        event: async ({ event }) => {
            const sound = EVENT_TO_SOUND[event.type];
            if (!sound) {
                return;
            }
            playSound(sound);
        },
        "permission.ask": async (_, output) => {
            if (output.status !== "ask") {
                return;
            }
            playSound("question");
        },
    };
};
export default SoundHooksPlugin;
//# sourceMappingURL=index.js.map
